"""Full native generated bytes, not only metadata hiding render defects."""
import pytest

from python.modules.editing.split_py.tests.plan_cases import SUCCESSES, prepared


@pytest.mark.parametrize('case', SUCCESSES, ids=lambda c:c['id'])
def test_native_generated_content(case):
    result = prepared(case)
    native = case['reference_result']
    assert result['facade'] == native['facade']
    assert result['modules'] == native['modules']


def test_join_blocks_and_long_import():
    from python.modules.editing.split_py.domain.facade import _format_import, _join_blocks
    assert _join_blocks([None,'','\n a \n','b\n']) == ' a \n\nb\n'
    names = ['very_long_name_%02d' % i for i in range(8)]
    assert _format_import('part',names) == 'from part import (%s)' % ',\n    '.join(names)


def test_cycle_order_and_acyclic():
    from python.modules.editing.split_py.domain.facade import _find_cycle
    assert _find_cycle({'z':{'a'},'a':{'z'}}) == ['a','z','a']
    assert _find_cycle({'a':{'b'},'b':set()}) is None
